// Kalkulator lot berdasarkan risiko (ringkas)
function hitungLot(balance: number, riskPersen: number,
                   slPip: number, nilaiPerPip: number) {
  const risikoUang = balance * (riskPersen / 100);
  const lot = risikoUang / (slPip * nilaiPerPip);
  return Math.max(0.01, Math.floor(lot * 100) / 100);
}

