// Susun laporan WhatsApp: nama saja, urut A–Z
function laporanWA(items, statusPerItem) {
  const ready  = items.filter(i => statusPerItem[i] === 'Ready');
  const kosong = items.filter(i => statusPerItem[i] === 'Kosong');
  ready.sort(); kosong.sort();
  return 'READY:\n' + ready.join('\n') +
         '\n\nKOSONG:\n' + kosong.join('\n');
}

